from google.cloud import texttospeech


def get_speech_client():
    return texttospeech.TextToSpeechClient()

from google.cloud.texttospeech import types


def normalize_payload(payload):
    return {
        "text": payload.get("text", ""),
        "ssml": payload.get("ssml", ""),
        "language_code": payload.get("language_code", "en-US")
    }


def normalize_response(response):
    return {
        "audio_bytes": response.audio_content,
        "content_type": response.audio_config.audio_encoding
    }

from google.cloud import translate


def translate_script(script, target_language):
    client = translate.TranslationServiceClient()
    response = client.translate_text(request={
        "parent": "projects/YOUR_PROJECT_ID/locations/global",
        "contents": [script],
        "target_language_code": target_language
    })
    return response.translations[0].translated_text

import re


def check_script_safety(script):
    unsafe_patterns = [
        r"hate speech",
        r"violence",
        r"discrimination"
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, script, re.IGNORECASE):
            return False
    return True

from google.cloud import speech


def transcribe_tts_qa_sample(audio_bytes):
    client = speech.SpeechClient()
    response = client.recognize(config={
        "encoding": speech.RecognitionConfig.AudioEncoding.LINEAR16,
        "sample_rate_hertz": 16000,
        "language_code": "en-US"
    }, audio={
        "content": audio_bytes.decode('base64')
    })
    return response.results[0].alternatives[0].transcript
